+    /// bounds are already farther than `cap`.
+    fn dist(&self, q: Point2, cap: f64) -> f64 {
+        let dx = (self.lo.x - q.x).max(q.x - self.hi.x).max(0.0);
+        let dy = (self.lo.y - q.y).max(q.y - self.hi.y).max(0.0);
+        if dx.hypot(dy) > cap {
