+    fn samples(&self, a: Point2, b: Point2) -> Vec<Point2> {
+        let len = (b.x - a.x).hypot(b.y - a.y);
+        let step = STEP * self.r;
+        let n = if len.is_finite() && step > 0.0 { (len / step).ceil().clamp(1.0, 1e6) } else { 1.0 };
+        let n = n as usize;
+        (0..=n).map(|i| {
+            let t = i as f64 / n as f64;
