+            let fixture = !keep.is_empty() && pts.iter().any(|&q| in_area(keep, q) || to_loops(q, keep.loops()) <= self.r);
+            return Err(LiftReason(if fixture { HITS_FIXTURE } else { CUTS_PART }));
+        }
