+            return Err(LiftReason(CROSSES_CUT));
+        }
+        let reach = SWATH * self.r;
+        if !pts.iter().all(|&q| in_area(air, q) || self.made.iter().any(|l| l.dist(q, reach) <= reach)) {
+            return Err(LiftReason(UNCUT_STOCK));
+        }
