+        proof.ends = (s, b);
+        let ok = proof.chord(s, b, Some(last)).is_ok();
+        proof.ends = (a, b);
+        if ok {
+            let mut out = back;
+            out.push(b);
+            return Ok(out);
+        }
+    }
