+/// The signed area of a closed curve: above 0 when it runs counter-clockwise.
+fn turn(c: &Curve) -> f64 {
+    let p: Vec<Point2> = c.pts().iter().map(|q| q.at()).collect();
+    p.iter().zip(p.iter().cycle().skip(1)).map(|(a, b)| a.x * b.y - b.x * a.y).sum::<f64>() / 2.0
+}
